create table if not exists public.scrap_app_state(id text primary key,payload jsonb not null default '{"splits":[],"inputs":[]}'::jsonb,revision bigint not null default 1,updated_at timestamptz not null default now());insert into public.scrap_app_state(id,payload) values('main','{"splits":[],"inputs":[]}'::jsonb) on conflict(id) do nothing;alter table public.scrap_app_state enable row level security;drop policy if exists "scrap public read" on public.scrap_app_state;drop policy if exists "scrap public insert" on public.scrap_app_state;drop policy if exists "scrap public update" on public.scrap_app_state;create policy "scrap public read" on public.scrap_app_state for select to anon,authenticated using(true);create policy "scrap public insert" on public.scrap_app_state for insert to anon,authenticated with check(id='main');create policy "scrap public update" on public.scrap_app_state for update to anon,authenticated using(id='main') with check(id='main');grant select,insert,update on public.scrap_app_state to anon,authenticated;create table if not exists public.scrap_photos(id uuid primary key default gen_random_uuid(),owner_type text not null,owner_key text not null,category text not null,object_path text not null unique,size_bytes bigint not null,created_at timestamptz not null default now());alter table public.scrap_photos enable row level security;drop policy if exists "scrap photo metadata read" on public.scrap_photos;drop policy if exists "scrap photo metadata insert" on public.scrap_photos;create policy "scrap photo metadata read" on public.scrap_photos for select to anon,authenticated using(true);create policy "scrap photo metadata insert" on public.scrap_photos for insert to anon,authenticated with check(true);grant select,insert on public.scrap_photos to anon,authenticated;insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('scrap-photos','scrap-photos',true,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;drop policy if exists "scrap photo public read" on storage.objects;drop policy if exists "scrap photo public upload" on storage.objects;create policy "scrap photo public read" on storage.objects for select to anon,authenticated using(bucket_id='scrap-photos');create policy "scrap photo public upload" on storage.objects for insert to anon,authenticated with check(bucket_id='scrap-photos');